	var _ /* day at bp+12 */ int32
	var _ /* mins at bp+0 */ int32
	var _ /* mon at bp+8 */ int32
	var _ /* year at bp+4 */ int32
	_, _, _, _, _, _, _, _, _, _, _, _, _, _, _ = H, L, M, T, UT, a, a_hr, cosDelta, cosH, hours, latitude, local, longdeg, sinDelta, t
	/* Get offset from UTC */
	if XCalculateUTC != 0 {
		if XCalcMinsFromUTC(tls, dse, libc.Int32FromInt32(12)*libc.Int32FromInt32(60), bp, libc.UintptrFromInt32(0)) != 0 {
			XEprint(tls, XGetErr(tls, int32(m_E_MKTIME_PROBLEM)), 0)
			return int32(m_INT_MAX2)
		}
	} else {
		**(**int32)(__ccgo_up(bp)) = XMinsFromUTC
	}
	/* Get latitude and longitude */
	longdeg = -XLongitude
	latitude = float64(libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) * XLatitude)
	XFromDSE(tls, dse, bp+4, bp+8, bp+12)
	/* Following formula on page B6 exactly... */
	t = float64(dse)
	if rise != 0 {
		t = t + (float64(6)+longdeg/float64(15))/float64(24)
	} else {
		t = t + (float64(18)+longdeg/float64(15))/float64(24)
	}
	/* Mean anomaly of sun starting from 1 Jan 1990 */
	/* NOTE: This assumes that BASE = 1990!!! */
	t = float64(float64(0.9856002585) * t)
	M = t + float64(357.828757) /* In degrees */
	/* Make sure M is in the range [0, 360) */
	M = M - float64(libc.Xfloor(tls, M/float64(360))*float64(360))
	/* Sun's true longitude */
	L = M + float64(float64(1.916)*libc.Xsin(tls, float64(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180)*M))) + float64(float64(0.02)*libc.Xsin(tls, float64(float64(libc.Float64FromInt32(2)*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180)))*M))) + float64(283.07080214)
	if L > float64(360) {
		L = L - float64(360)
	}
	/* Tan of sun's right ascension */
	a = float64(libc.Float64FromFloat64(180) / libc.Float64FromFloat64(3.141592653589793) * libc.Xatan2(tls, float64(float64(0.91746)*libc.Xsin(tls, float64(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180)*L))), libc.Xcos(tls, float64(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180)*L))))
