/* The following sets of functions are for computing solstices and equinoxes.
   They are based on the algorithms described in "Astronomical Algorithms",
   second edition, by Jean Meeus.  ISBN 0-943396-61-1 */

// C documentation
//
//	/* The following are taken from Astronomical Algorithms, 2nd ed., page 178 */
func _mean_march_equinox(tls *libc.TLS, y float64) (r float64) {
	return float64(2.45162380984e+06) + float64(float64(365242.37404)*y) + float64(float64(float64(0.05169)*y)*y) - float64(float64(float64(float64(0.00411)*y)*y)*y) - float64(float64(float64(float64(float64(0.00057)*y)*y)*y)*y)
}

func _mean_june_solstice(tls *libc.TLS, y float64) (r float64) {
	return float64(2.45171656767e+06) + float64(float64(365241.62603)*y) + float64(float64(float64(0.00325)*y)*y) + float64(float64(float64(float64(0.00888)*y)*y)*y) - float64(float64(float64(float64(float64(0.0003)*y)*y)*y)*y)
}

func _mean_september_equinox(tls *libc.TLS, y float64) (r float64) {
	return float64(2.45181021715e+06) + float64(float64(365242.01767)*y) - float64(float64(float64(0.11575)*y)*y) + float64(float64(float64(float64(0.00337)*y)*y)*y) + float64(float64(float64(float64(float64(0.00078)*y)*y)*y)*y)
}

func _mean_december_solstice(tls *libc.TLS, y float64) (r float64) {
	return float64(2.45190005952e+06) + float64(float64(365242.74049)*y) - float64(float64(float64(0.06223)*y)*y) - float64(float64(float64(float64(0.00823)*y)*y)*y) + float64(float64(float64(float64(float64(0.00032)*y)*y)*y)*y)
}

