// C documentation
//
//	/***************************************************************/
//	/*                                                             */
//	/*  jdate                                                      */
//	/*                                                             */
//	/*  Convert a date and time to Julian day and fraction.        */
//	/*                                                             */
//	/***************************************************************/
func _jdate(tls *libc.TLS, y int32, mon int32, day int32) (r int64) {
	var c, m int64
	_, _ = c, m
	m = int64(mon + int32(1))
	if m > int64(2) {
		m = m - int64(3)
	} else {
		m = m + int64(9)
		y = y - 1
	}
	c = int64(y) / int64(100) /* Century */
	y = int32(int64(y) - libc.Int64FromInt64(100)*c)
	return int64(day) + c*int64(146097)/int64(4) + int64(y)*int64(1461)/int64(4) + (m*int64(153)+int64(2))/int64(5) + int64(1721119)
}

// C documentation
//
//	/***************************************************************/
//	/*                                                             */
//	/*  jtime                                                      */
//	/*                                                             */
//	/*  Convert a GMT date and time to astronomical Julian time,   */
//	/*  i.e. Julian date plus day fraction, expressed as a double  */
//	/*                                                             */
//	/***************************************************************/
func _jtime(tls *libc.TLS, y int32, mon int32, day int32, hour int32, min int32, sec int32) (r float64) {
	return float64(_jdate(tls, y, mon, day)) - float64(0.5) + float64(int64(sec)+libc.Int64FromInt64(60)*int64(min)+libc.Int64FromInt64(3600)*int64(hour))/float64(86400)
}

// C documentation
//
//	/***************************************************************/
//	/*                                                             */
//	/*  jyear                                                      */
//	/*                                                             */
//	/*  Convert a Julian date to year, month, day.                 */
//	/*                                                             */
//	/***************************************************************/
func _jyear(tls *libc.TLS, td float64, yy uintptr, mm uintptr, dd uintptr) {
	var d, j, m, y float64
	_, _, _, _ = d, j, m, y
	td = td + float64(0.5) /* Astronomical to civil */
	j = libc.Xfloor(tls, td)
	j = j - float64(1.721119e+06)
	y = libc.Xfloor(tls, (float64(libc.Float64FromInt32(4)*j)-libc.Float64FromInt32(1))/float64(146097))
	j = float64(j*float64(4)) - (float64(1) + float64(float64(146097)*y))
	d = libc.Xfloor(tls, j/float64(4))
	j = libc.Xfloor(tls, (float64(float64(4)*d)+float64(3))/float64(1461))
	d = float64(float64(4)*d) + float64(3) - float64(float64(1461)*j)
	d = libc.Xfloor(tls, (d+float64(4))/float64(4))
	m = libc.Xfloor(tls, (float64(float64(5)*d)-libc.Float64FromInt32(3))/float64(153))
	d = float64(float64(5)*d) - (float64(3) + float64(float64(153)*m))
	d = libc.Xfloor(tls, (d+float64(5))/float64(5))
	y = float64(float64(100)*y) + j
	if m < float64(10) {
		m = m + libc.Float64FromInt32(2)
	} else {
		m = m - libc.Float64FromInt32(10)
		y = y + libc.Float64FromInt32(1)
	}
	**(**int32)(__ccgo_up(yy)) = int32(y)
	**(**int32)(__ccgo_up(mm)) = int32(m)
	**(**int32)(__ccgo_up(dd)) = int32(d)
}

// C documentation
//
//	/***************************************************************/
//	/*                                                             */
//	/*  jhms                                                       */
//	/*                                                             */
//	/*  Convert a Julian time to hour, minutes and seconds.        */
//	/*                                                             */
//	/***************************************************************/
func _jhms(tls *libc.TLS, j float64, h uintptr, m uintptr, s uintptr) {
	var ij int64
	_ = ij
	j = j + float64(0.5) /* Astronomical to civil */
	ij = int64((j - libc.Xfloor(tls, j)) * float64(86400))
	**(**int32)(__ccgo_up(h)) = int32(ij / int64(3600))
	**(**int32)(__ccgo_up(m)) = int32(ij / int64(60) % int64(60))
	**(**int32)(__ccgo_up(s)) = int32(ij % int64(60))
}

