/* How many hours to search for moonrise / moonset?  We search
   half a window on either side of the starting point */

/* K1 tide cycle is 1.0027379 cycles per solar day */

type TMoonInfo = struct {
	FqueryTime Ttime_t
	FriseTime  Ttime_t
	FsetTime   Ttime_t
	FriseAz    float64
	FsetAz     float64
	FhasRise   int32
	FhasSet    int32
	FisVisible int32
}

func _init_moon_info(tls *libc.TLS, info uintptr) {
	(*TMoonInfo)(unsafe.Pointer(info)).FqueryTime = libc.Int64FromInt32(0)
	(*TMoonInfo)(unsafe.Pointer(info)).FriseTime = libc.Int64FromInt32(0)
	(*TMoonInfo)(unsafe.Pointer(info)).FsetTime = libc.Int64FromInt32(0)
	(*TMoonInfo)(unsafe.Pointer(info)).FriseAz = float64(0)
	(*TMoonInfo)(unsafe.Pointer(info)).FsetAz = float64(0)
	(*TMoonInfo)(unsafe.Pointer(info)).FhasRise = 0
	(*TMoonInfo)(unsafe.Pointer(info)).FhasSet = 0
	(*TMoonInfo)(unsafe.Pointer(info)).FisVisible = 0
}

